macro_rules! deps {
    () => {
        Fork!();
        Result!();
    };
}

macro_rules! kernel_fork {
    () => {
        deps!();
        # [doc = " `fork()`—Creates a new process by duplicating the calling process."] # [doc = ""] # [doc = " On success, `Fork::ParentOf` containing the pid of the child process is"] # [doc = " returned in the parent, and `Fork::Child` containing the pid of the child"] # [doc = " process is returned in the child."] # [doc = ""] # [doc = " Unlike its POSIX and libc counterparts, this `fork` does not invoke any"] # [doc = " handlers (such as those registered with `pthread_atfork`)."] # [doc = ""] # [doc = " The program environment in the child after a `fork` and before an `execve`"] # [doc = " is very special. All code that executes in this environment must avoid:"] # [doc = ""] # [doc = "  - Acquiring any other locks that are held in other threads on the parent"] # [doc = "    at the time of the `fork`, as the child only contains one thread, and"] # [doc = "    attempting to acquire such locks will deadlock (though this is [not"] # [doc = "    considered unsafe])."] # [doc = ""] # [doc = "  - Performing any dynamic allocation using the global allocator, since"] # [doc = "    global allocators may use locks to ensure thread safety, and their locks"] # [doc = "    may not be released in the child process, so attempts to allocate may"] # [doc = "    deadlock (as described in the previous point)."] # [doc = ""] # [doc = "  - Accessing any external state which the parent assumes it has exclusive"] # [doc = "    access to, such as a file protected by a file lock, as this could"] # [doc = "    corrupt the external state."] # [doc = ""] # [doc = "  - Accessing any random-number-generator state inherited from the parent,"] # [doc = "    as the parent may have the same state and generate the same random"] # [doc = "    numbers, which may violate security invariants."] # [doc = ""] # [doc = "  - Accessing any thread runtime state, since this function does not update"] # [doc = "    the thread id in the thread runtime, so thread runtime functions could"] # [doc = "    cause undefined behavior."] # [doc = ""] # [doc = "  - Accessing any memory shared with the parent, such as a [`MAP_SHARED`]"] # [doc = "    mapping, even with anonymous or [`memfd_create`] mappings, as this could"] # [doc = "    cause undefined behavior."] # [doc = ""] # [doc = "  - Calling any C function which isn't known to be [async-signal-safe], as"] # [doc = "    that could cause undefined behavior. The extent to which this also"] # [doc = "    applies to Rust functions is unclear at this time."] # [doc = ""] # [doc = "  - And more."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The child must avoid accessing any memory shared with the parent in a"] # [doc = " way that invokes undefined behavior. It must avoid accessing any threading"] # [doc = " runtime functions in a way that invokes undefined behavior. And it must"] # [doc = " avoid invoking any undefined behavior through any function that is not"] # [doc = " guaranteed to be async-signal-safe. But, what does async-signal-safe even"] # [doc = " mean in a Rust program? This documentation does not have all the answers."] # [doc = ""] # [doc = " So you're on your own. And on top of all the troubles with `fork` in"] # [doc = " general, this wrapper implementation is highly experimental."] # [doc = ""] # [doc = " # References"] # [doc = "  - [POSIX]"] # [doc = "  - [Linux]"] # [doc = ""] # [doc = " # Literary interlude"] # [doc = ""] # [doc = " > Do not jump on ancient uncles."] # [doc = " > Do not yell at average mice."] # [doc = " > Do not wear a broom to breakfast."] # [doc = " > Do not ask a snake’s advice."] # [doc = " > Do not bathe in chocolate pudding."] # [doc = " > Do not talk to bearded bears."] # [doc = " > Do not smoke cigars on sofas."] # [doc = " > Do not dance on velvet chairs."] # [doc = " > Do not take a whale to visit"] # [doc = " > Russell’s mother’s cousin’s yacht."] # [doc = " > And whatever else you do do"] # [doc = " > It is better you"] # [doc = " > Do not."] # [doc = ""] # [doc = " — “Rules”, by Karla Kuskin"] # [doc = ""] # [doc = " [`MAP_SHARED`]: https://pubs.opengroup.org/onlinepubs/9799919799/functions/mmap.html"] # [doc = " [not considered unsafe]: https://doc.rust-lang.org/reference/behavior-not-considered-unsafe.html#deadlocks"] # [doc = " [`memfd_create`]: https://man7.org/linux/man-pages/man2/memfd_create.2.html"] # [doc = " [POSIX]: https://pubs.opengroup.org/onlinepubs/9799919799/functions/fork.html"] # [doc = " [Linux]: https://man7.org/linux/man-pages/man2/fork.2.html"] # [doc = " [async-signal-safe]: https://pubs.opengroup.org/onlinepubs/9799919799/functions/V2_chap02.html#tag_15_04_03"] pub unsafe fn kernel_fork () -> io :: Result < Fork > { backend :: runtime :: syscalls :: kernel_fork () }
    };
}

kernel_fork!()